import{_ as n,C as l,c as o,o as i,a2 as a,b as r,w as s,a as p,G as d,a3 as u}from"./chunks/framework.DkPtUiZm.js";const y=JSON.parse('{"title":"Publier SIA UI Demo sur Google Play","description":"","frontmatter":{},"headers":[],"relativePath":"guides/publication-google-play.md","filePath":"guides/publication-google-play.md","lastUpdated":1795438092000}'),c={name:"guides/publication-google-play.md"};function h(m,e,g,k,f,v){const t=l("Mermaid");return i(),o("div",null,[e[1]||(e[1]=a('<h1 id="publier-sia-ui-demo-sur-google-play" tabindex="-1">Publier SIA UI Demo sur Google Play <a class="header-anchor" href="#publier-sia-ui-demo-sur-google-play" aria-label="Permalink to &quot;Publier SIA UI Demo sur Google Play&quot;">​</a></h1><h2 id="etat-de-la-preparation" tabindex="-1">État de la préparation <a class="header-anchor" href="#etat-de-la-preparation" aria-label="Permalink to &quot;État de la préparation&quot;">​</a></h2><p>Le dépôt contient la configuration Android/EAS et une page de confidentialité accessible avant connexion et depuis Compte. La liaison au compte Expo se fait avec <code>eas init</code>, qui renseigne la configuration locale. Cette préparation ne garantit ni la réussite d&#39;un build signé ni un envoi sur Google Play.</p><table tabindex="0"><thead><tr><th>Élément</th><th>Valeur préparée</th></tr></thead><tbody><tr><td>Nom public proposé</td><td>SIA UI Demo</td></tr><tr><td>Slug Expo</td><td>sia-ui-native-demo</td></tr><tr><td>Identifiant Android proposé</td><td>com.jodemi.siauidemo</td></tr><tr><td>Version de l’application</td><td>1.0.0, indépendante de la version npm de SIA UI</td></tr><tr><td>Version de build</td><td>Gestion distante EAS, incrément automatique en production</td></tr><tr><td>preview</td><td>APK installable directement, distribution interne EAS</td></tr><tr><td>production</td><td>AAB destiné à Google Play</td></tr><tr><td>Soumission EAS facultative</td><td>Piste internal, statut draft ; pas de diffusion publique automatique</td></tr><tr><td>Signature</td><td>Gérée à la demande par EAS ; clés et identifiants hors du dépôt</td></tr></tbody></table><p>Confirmer l’identifiant Android <strong>avant le premier dépôt sur Google Play</strong> : il identifie l’application et ne se renomme pas ensuite comme un simple titre. Le remplacer dans app.json si un autre nom est choisi.</p>',5)),(i(),r(u,null,{default:s(()=>[d(t,{id:"mermaid-98",class:"mermaid",graph:"flowchart%20LR%0A%20%20Depot%5BConfiguration%20et%20sources%20du%20monorepo%5D%20--%3E%20Outils%5B%22Node%2024.19.0%20et%20pnpm%2012.21.0%3Cbr%2F%3ECorepack%20d%C3%A9sactiv%C3%A9%22%5D%0A%20%20Outils%20--%3E%20EAS%5BBuild%20EAS%20et%20signature%5D%0A%20%20EAS%20--%3E%20APK%5BAPK%20de%20pr%C3%A9visualisation%5D%0A%20%20EAS%20--%3E%20AAB%5BAAB%20de%20production%5D%0A%20%20AAB%20--%3E%20Interne%5BGoogle%20Play%20%3A%20test%20interne%5D%0A%20%20Interne%20--%3E%20Conditions%5BTests%20et%20conditions%20du%20compte%20d%C3%A9veloppeur%5D%0A%20%20Conditions%20--%3E%20Public%5BDemande%20de%20diffusion%20publique%20et%20revue%20Google%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>Le schéma officiel EAS a validé les profils résolus. La génération native Expo confirme le package, le nom, le thème système et les règles de retrait des permissions. La validation du manifeste fusionné dans un AAB signé reste à faire après le build EAS. Le module expo-system-ui est installé dans la démo pour appliquer le mode système en application autonome. Le template ne demande plus de permission de superposition.</p><h2 id="_1-preparer-les-comptes-et-les-informations" tabindex="-1">1. Préparer les comptes et les informations <a class="header-anchor" href="#_1-preparer-les-comptes-et-les-informations" aria-label="Permalink to &quot;1. Préparer les comptes et les informations&quot;">​</a></h2><ul><li>Un compte Expo et un compte développeur Google Play Console activé et vérifié.</li><li>Le nom d’éditeur, l’adresse de contact requise par Google et l’identifiant Android définitif.</li><li>Les conditions de test indiquées dans Play Console pour ce compte. Un nouveau compte personnel peut nécessiter un test fermé avant l’accès à la production ; le test interne seul ne remplit pas nécessairement ces conditions.</li><li>Une URL HTTPS publique de la politique de confidentialité. Le <a href="./../legal/confidentialite-demo-mobile.html">texte préparé</a> doit être relu et adapté à l’éditeur affiché sur la fiche.</li></ul><p>Les éventuels frais Google et les quotas/coûts EAS sont à vérifier dans les comptes. Les versions de pnpm et Node du profil EAS correspondent à celles utilisées pour valider la démo. L’image Android et la cible SDK restent celles du SDK Expo installé ; vérifier leur conformité aux exigences affichées dans Play Console lors du dépôt.</p><h3 id="installer-pnpm-sur-le-serveur-eas" tabindex="-1">Installer pnpm sur le serveur EAS <a class="header-anchor" href="#installer-pnpm-sur-le-serveur-eas" aria-label="Permalink to &quot;Installer pnpm sur le serveur EAS&quot;">​</a></h3><p>Le profil commun <code>build.base</code> fixe Node 24.19.0 et pnpm 12.21.0, aligné sur le champ <code>packageManager</code> du monorepo. Les profils <code>preview</code> et <code>production</code> en héritent. <strong>Corepack reste désactivé</strong> dans ce profil : EAS installe lui-même la version demandée avec npm.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;24.19.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pnpm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;12.21.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;corepack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Avec <code>corepack: true</code>, le worker peut créer un lanceur <code>pnpm</code>, puis tenter <code>npm -g install pnpm@12.21.0</code> au même emplacement. Les logs affichent alors <code>npm error EEXIST: file already exists</code> avant le message générique <code>Failed to install pnpm</code>. Ce cas a été confirmé sur le premier essai Android. Il se produit pendant l&#39;installation des outils, avant l&#39;installation du workspace et les hooks de l&#39;application : modifier <code>eas-build-pre-install</code> ne corrigerait pas cette étape. Garder <code>corepack: false</code>, puis relancer la commande du profil voulu.</p><p>Voir la <a href="https://docs.expo.dev/eas/json/" target="_blank" rel="noreferrer">configuration officielle EAS</a> et le <a href="https://github.com/expo/eas-cli/issues/3148" target="_blank" rel="noreferrer">conflit Corepack/pnpm documenté par Expo</a>.</p><h2 id="_2-lier-expo-au-bon-compte" tabindex="-1">2. Lier Expo au bon compte <a class="header-anchor" href="#_2-lier-expo-au-bon-compte" aria-label="Permalink to &quot;2. Lier Expo au bon compte&quot;">​</a></h2><p>Depuis la racine du monorepo, sous PowerShell, Bash ou un terminal équivalent :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/native-demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eas-cli@27.11.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eas-cli@27.11.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eas-cli@27.11.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>Choisir le bon compte ou la bonne organisation Expo. <code>init</code> ajoute notamment le vrai extra.eas.projectId à la configuration ; il n’est pas remplacé par un UUID fictif dans le dépôt. Relire puis conserver cette modification dans Git.</p><p>Les commandes EAS suivantes sont également lancées depuis apps/native-demo. Dans le cloud, EAS installe le workspace ; le hook eas-build-post-install construit les packages SIA nécessaires depuis leurs sources locales. La démo n’a donc pas besoin d’attendre une publication npm pour les utiliser.</p><h2 id="_3-construire-et-tester-un-apk-autonome" tabindex="-1">3. Construire et tester un APK autonome <a class="header-anchor" href="#_3-construire-et-tester-un-apk-autonome" aria-label="Permalink to &quot;3. Construire et tester un APK autonome&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:android:preview</span></span></code></pre></div><p>Au premier build, EAS peut proposer de créer les identifiants de signature Android. Laisser EAS gérer une nouvelle clé seulement s’il s’agit bien d’une nouvelle app ; pour une app existante, conserver les identifiants utilisés précédemment.</p><p>Télécharger l’APK fourni par EAS et l’installer sur un appareil autorisant cette installation. Il fonctionne sans Expo Go et sans serveur Metro.</p><p>Tester au minimum :</p><ol><li>Démarrage à froid, typographie et icône sur le lanceur ; ouvrir le catalogue.</li><li>Session locale Membre puis Administrateur ; aucun compte externe n’est demandé.</li><li>Thème clair/sombre, couleurs, navigation et redémarrage après modification.</li><li>Clavier, commandes de champ suivant/précédent et formulaires bas de page.</li><li>BottomSheet : poignée, contenu long, clavier, crans et fermeture.</li><li>Choix d’un document/photo, puis refus et autorisation de la caméra ; aucune demande de microphone ou d’accès global aux photos.</li><li>Page Confidentialité avant connexion puis depuis Compte ; Retour et bouton Android système.</li><li>Mode avion, absence de service métier nécessaire, passage en arrière-plan et reprise.</li><li>Effacer les données dans Android, puis relancer la démo dans son état initial.</li></ol><h2 id="_4-preparer-la-fiche-et-la-politique-de-confidentialite" tabindex="-1">4. Préparer la fiche et la politique de confidentialité <a class="header-anchor" href="#_4-preparer-la-fiche-et-la-politique-de-confidentialite" aria-label="Permalink to &quot;4. Préparer la fiche et la politique de confidentialité&quot;">​</a></h2><p>Le fichier <code>.easignore</code> à la racine reprend les exclusions de <code>.gitignore</code> et écarte <code>docs/assets/google-play/</code> et la copie de <code>.git</code> de l’archive envoyée à EAS. Cette copie peut contenir les objets Git des visuels même si les fichiers eux-mêmes sont exclus. Les visuels restent disponibles pour la fiche et le site documentaire. Lors d’un changement des exclusions Git qui concerne aussi la compilation, mettre à jour les deux fichiers, car EAS utilise <code>.easignore</code> en priorité.</p><p>La configuration Expo demande l’orientation portrait. Pendant la génération Android, le plugin local <code>with-optional-portrait.cjs</code> déclare <code>android.hardware.screen.portrait</code> avec <code>android:required=&quot;false&quot;</code> dans le manifeste. Google Play peut ainsi proposer l’installation sur les appareils qui ne déclarent pas cette fonctionnalité. Pour appliquer le changement à une version déjà importée, produire un nouvel AAB avec un code de version supérieur.</p><p>Le <a href="./fiche-google-play.html">texte de fiche proposé</a> distingue la description publique des indications destinées au relecteur Google. Produire les captures depuis l’APK final avec des données fictives : catalogue, thèmes, formulaire, feuille, parcours Contacts. Elles doivent montrer le rendu de l’app réellement envoyée.</p><p>Google demande notamment une icône de fiche 512 × 512, une image de présentation 1024 × 500 et des captures respectant les contraintes de Play Console. Les assets de lanceur du dépôt ne remplacent pas tous ces visuels. Le <a href="./visuels-google-play.html">lot de visuels Google Play</a> fournit l&#39;icône, deux bannières, huit compositions avec téléphones et des captures simples claires et sombres, préparées depuis l&#39;APK preview 1.0.0. Vérifier leur correspondance avec l&#39;APK final avant l&#39;envoi.</p><p>Publier la politique sur le site documentaire ou un autre hébergement HTTPS public, puis vérifier son ouverture sans authentification. La politique locale dans l’app n’établit pas que la page du site a été déployée. Fournir la vraie URL dans Play Console. Revoir le nom de l’éditeur et le contact avant la diffusion.</p><p>Pour « Sécurité des données », la base actuelle ne contient ni service métier, publicité ni mesure d’audience du projet. Les saisies et sélections restent locales, et les partages sont déclenchés par l’utilisateur. Vérifier le build final et ses SDK avant de remplir le formulaire ; ne pas déclarer la caméra comme une collecte serveur simplement parce qu’une photo peut être prise localement.</p><p>La session simulée ne crée pas de compte distant. Pour le champ d’accès à l’app, expliquer le choix de rôle local et donner les étapes de la fiche proposée. Renseigner les autres rubriques demandées : public visé, classification, publicité, coordonnées et accès. Les réponses doivent correspondre à l’app finale.</p><h2 id="_5-construire-l-aab-pour-google-play" tabindex="-1">5. Construire l’AAB pour Google Play <a class="header-anchor" href="#_5-construire-l-aab-pour-google-play" aria-label="Permalink to &quot;5. Construire l’AAB pour Google Play&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:android:production</span></span></code></pre></div><p>Télécharger l’AAB depuis la page du build EAS. C’est ce fichier qu’attend Google Play ; l’export JavaScript <code>pnpm native:export</code> et l’APK preview ne le remplacent pas. Ne pas ajouter de projetId, clé privée ou compte de service factice pour contourner une étape de connexion. Conserver les clés EAS et activer Play App Signing selon le parcours Google ; la clé d’envoi et la clé de distribution ont des rôles différents.</p><h2 id="_6-premier-envoi-manuel-dans-play-console" tabindex="-1">6. Premier envoi manuel dans Play Console <a class="header-anchor" href="#_6-premier-envoi-manuel-dans-play-console" aria-label="Permalink to &quot;6. Premier envoi manuel dans Play Console&quot;">​</a></h2><ol><li>Créer l’application avec son nom, sa langue et le type application.</li><li>Préparer la piste <strong>Test interne</strong> et y déposer l’AAB.</li><li>Compléter les rubriques de contenu, l’accès et la politique de confidentialité.</li><li>Ajouter les testeurs et démarrer la diffusion interne selon les étapes de la Console.</li><li>Ouvrir le lien d’inscription au test avec un compte autorisé, puis installer depuis Google Play.</li><li>Refaire les parcours sur cette installation ; consulter les rapports de pré-lancement et résoudre les blocages.</li><li>Suivre ensuite les conditions de test/accès à la production affichées pour le compte, puis demander la publication publique.</li></ol><p>Le premier dépôt est manuel. Il permet de vérifier le package, la signature et le contenu avant d’automatiser une soumission. Google décide de l’acceptation et du délai.</p><h2 id="_7-envois-suivants-si-souhaite" tabindex="-1">7. Envois suivants, si souhaité <a class="header-anchor" href="#_7-envois-suivants-si-souhaite" aria-label="Permalink to &quot;7. Envois suivants, si souhaité&quot;">​</a></h2><p>Après le premier dépôt et la configuration de l’accès à l’API Google Play avec un compte de service autorisé :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eas-cli@27.11.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --latest</span></span></code></pre></div><p>Vérifier que le dernier build est bien celui voulu ; sinon sélectionner son ID avec les options de la CLI. Le profil garde la soumission en test interne et en brouillon. EAS demande les vrais identifiants nécessaires : ils ne sont pas committés. La mise en production publique reste une étape distincte dans Google Play.</p><h2 id="liens-de-reference" tabindex="-1">Liens de référence <a class="header-anchor" href="#liens-de-reference" aria-label="Permalink to &quot;Liens de référence&quot;">​</a></h2><ul><li><a href="https://docs.expo.dev/build-reference/build-with-monorepos/" target="_blank" rel="noreferrer">EAS Build en monorepo</a>.</li><li><a href="https://docs.expo.dev/deploy/build-project/" target="_blank" rel="noreferrer">Distribution Android</a>.</li><li><a href="https://docs.expo.dev/submit/android/" target="_blank" rel="noreferrer">Soumission Google Play</a>.</li><li><a href="https://play.google.com/console/" target="_blank" rel="noreferrer">Play Console</a>.</li></ul>`,40))])}const E=n(c,[["render",h]]);export{y as __pageData,E as default};
